update public.products set description='Fresh beef portions with bone, suitable for soups, stews, sauces and other dishes where bone-in beef is preferred.', handling_protocols=array['Keep raw beef cold and separate from cooked foods, vegetables and other ready-to-eat items.','Do not wash raw beef for food-safety purposes; clean hands, knives, boards and surfaces after handling.','For intact beef cuts, cook to at least 63°C / 145°F and allow a 3-minute rest.']::text[], storage_tips=array['Because the exact cut style is not defined, refrigerate at 4°C or below and use within about 1–2 days.','For longer storage, freeze promptly at about -18°C or below and use within about 4–6 months for best quality.']::text[] where name='Beef Bone-in Cuts' and category_id=(select id from public.product_categories where name='Meat & Poultry');
update public.products set description='Fresh boneless beef portions with the bone removed, suitable for stews, soups, sauces, stir-fries and a range of everyday beef dishes.', handling_protocols=array['Keep raw beef cold and separate from ready-to-eat foods.','Do not wash raw beef for food-safety purposes; clean hands, knives, boards and surfaces after handling.','For intact whole-muscle portions, cook to at least 63°C / 145°F and allow a 3-minute rest.']::text[], storage_tips=array['Because the retail packs may contain portioned stew meat, refrigerate at 4°C or below and use within about 1–2 days.','For longer storage, freeze at about -18°C or below and use within about 4–6 months for best quality.']::text[] where name='Boneless Beef' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
